// Restore the source tree for the GitHub browser-upload edition.
const fs = require('node:fs');
const path = require('node:path');
const { gunzipSync } = require('node:zlib');
const { createHash } = require('node:crypto');

// Each entry stores a project-relative path and the original file bytes.
const packed = Buffer.from('', 'base64');
const digest = createHash('sha256').update(packed).digest('hex');
if (digest !== '1c12842bf9f0e8b914c108328e843f4d104c53978aae0f94fa3af4d375e644cd') throw new Error('The uploaded project data is incomplete.');
const entries = JSON.parse(gunzipSync(packed).toString('utf8'));
for (const [name, content] of entries) {
  const parts = name.split('/');
  if (parts.some(part => !part || part === '..' || part === '.' || part === '.git') || path.isAbsolute(name)) {
    throw new Error('Invalid project file path.');
  }
  const destination = path.join(__dirname, ...parts);
  if (fs.existsSync(destination)) continue;
  fs.mkdirSync(path.dirname(destination), {recursive:true});
  fs.writeFileSync(destination, Buffer.from(content, 'base64'), {flag:'wx'});
}
console.log('Portfolio source is ready.');
